async function loadUser(id: string): Promise<any> {
  const response = await fetch('/api/users/' + id);
  if (!response.ok) {
    throw new Error('bad status ' + response.status);
  }
  const user = await response.json();
  const orgResponse = await fetch('/api/orgs/' + user.orgId);
  if (!orgResponse.ok) {
    throw new Error('bad status ' + orgResponse.status);
  }
  const org = await orgResponse.json();
  user.org = org;
  return user;
}

async function loadUsers(ids: string[]): Promise<any[]> {
  const results = await Promise.all(ids.map(async (id) => {
    return await loadUser(id);
  }));
  return results;
}

module.exports = { loadUser, loadUsers };
